Here's a comprehensive guide to creating global popups in React:

## 1. **Context-Based Global Popup System**

### Create Popup Context

```jsx
// PopupContext.jsx
import React, { createContext, useContext, useState } from 'react';

const PopupContext = createContext();

export const usePopup = () => {
  const context = useContext(PopupContext);
  if (!context) {
    throw new Error('usePopup must be used within PopupProvider');
  }
  return context;
};

export const PopupProvider = ({ children }) => {
  const [popup, setPopup] = useState(null);

  const showPopup = (content, options = {}) => {
    setPopup({
      content,
      ...options,
      id: Date.now()
    });
  };

  const hidePopup = () => {
    setPopup(null);
  };

  return (
    <PopupContext.Provider value={{ showPopup, hidePopup, popup }}>
      {children}
      {popup && (
        <PopupContainer 
          popup={popup} 
          onClose={hidePopup}
        />
      )}
    </PopupContext.Provider>
  );
};
```

